#include <stdbool.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/syscall_handler.h>

/**
 * Verify each sqe by copying it in and validating its contents
 */
static inline bool rtio_vrfy_sqe(struct rtio *r, struct rtio_sqe *sqe,
				 struct rtio_sqe *sqe_iter)
{
	if (Z_SYSCALL_VERIFY(sqe->iodev == NULL ||
	    !z_S_O_IS_VALID(sqe->iodev, K_OBJ_RTIO_IODEV))) {
		return false;
	}

	switch (sqe->op) {
	case RTIO_OP_NOP:
		break;
	case RTIO_OP_RX:
		if ((sqe->flags & RTIO_SQE_MEMPOOL_BUFFER) == 0 &&
		    Z_SYSCALL_MEMORY_WRITE(sqe->buf, sqe->buf_len)) {
			return false;
		}
		break;
	case RTIO_OP_TX:
		if (Z_SYSCALL_MEMORY_READ(sqe->buf, sqe->buf_len)) {
			return false;
		}
		break;
	case RTIO_OP_TINY_TX:
		break;
	case RTIO_OP_TXRX:
		if (Z_SYSCALL_MEMORY_READ(sqe->tx_buf, sqe->txrx_buf_len)) {
			return false;
		}
		if (Z_SYSCALL_MEMORY_WRITE(sqe->rx_buf, sqe->txrx_buf_len)) {
			return false;
		}
		break;
	default:
		/* RTIO OP must be known and permissible from user mode
		 * otherwise it passes go directly to jail
		 */
		return false;
	}

	return true;
}

static inline int z_vrfy_rtio_cqe_get_mempool_buffer(const struct rtio *r,
						     const struct rtio_cqe *cqe,
						     uint8_t **buff,
						     uint32_t *buff_len)
{
	Z_OOPS(Z_SYSCALL_OBJ(r, K_OBJ_RTIO));
	Z_OOPS(Z_SYSCALL_MEMORY_READ(cqe, sizeof(struct rtio_cqe)));
	Z_OOPS(Z_SYSCALL_MEMORY_WRITE(buff, sizeof(void *)));
	Z_OOPS(Z_SYSCALL_MEMORY_WRITE(buff_len, sizeof(uint32_t)));
	return z_impl_rtio_cqe_get_mempool_buffer(r, cqe, buff, buff_len);
}
#include <syscalls/rtio_cqe_get_mempool_buffer_mrsh.c>

static inline void z_vrfy_rtio_release_buffer(struct rtio *r, void *buff, uint32_t buff_len)
{
	Z_OOPS(Z_SYSCALL_OBJ(r, K_OBJ_RTIO));
	z_impl_rtio_release_buffer(r, buff, buff_len);
}
#include <syscalls/rtio_release_buffer_mrsh.c>

static inline int z_vrfy_rtio_sqe_cancel(struct rtio_sqe *sqe)
{
	return z_impl_rtio_sqe_cancel(sqe);
}
#include <syscalls/rtio_sqe_cancel_mrsh.c>

static inline int z_vrfy_rtio_sqe_copy_in_get_handles(struct rtio *r,
						      const struct rtio_sqe *sqes,
						      struct rtio_sqe **handle,
						      size_t sqe_count)
{
	Z_OOPS(Z_SYSCALL_OBJ(r, K_OBJ_RTIO));

	if (handle != NULL) {
		Z_OOPS(Z_SYSCALL_MEMORY_ARRAY_WRITE(handle, sqe_count,
						    sizeof(struct rtio_sqe *)));
		*handle = NULL;
	}

	struct rtio_sqe *sqe;
	uint32_t acquirable = rtio_sqe_acquirable(r);

	if (acquirable < sqe_count) {
		return -ENOMEM;
	}

	Z_OOPS(Z_SYSCALL_MEMORY_ARRAY_READ(sqes, sqe_count,
					   sizeof(struct rtio_sqe)));

	for (int i = 0; i < sqe_count; i++) {
		sqe = rtio_sqe_acquire(r);
		__ASSERT_NO_MSG(sqe != NULL);
		if (handle != NULL && i == 0) {
			*handle = sqe;
		}
		*sqe = sqes[i];

		if (!rtio_vrfy_sqe(r, sqe, &r->sqe_pool[0])) {
			rtio_sqe_drop_all(r);
			Z_OOPS(true);
		}
	}

	/*Already copied *and* verified, no need to redo */
	return z_impl_rtio_sqe_copy_in_get_handles(r, NULL, NULL, 0);
}
#include <syscalls/rtio_sqe_copy_in_get_handles_mrsh.c>

static inline int z_vrfy_rtio_cqe_copy_out(struct rtio *r,
					   struct rtio_cqe *cqes,
					   size_t cqe_count,
					   k_timeout_t timeout)
{
	Z_OOPS(Z_SYSCALL_OBJ(r, K_OBJ_RTIO));

	Z_OOPS(Z_SYSCALL_MEMORY_ARRAY_WRITE(cqes, cqe_count,
					    sizeof(struct rtio_cqe)));

	return z_impl_rtio_cqe_copy_out(r, cqes, cqe_count, timeout);
}
#include <syscalls/rtio_cqe_copy_out_mrsh.c>

static inline int z_vrfy_rtio_submit(struct rtio *r, uint32_t wait_count)
{
	Z_OOPS(Z_SYSCALL_OBJ(r, K_OBJ_RTIO));

#ifdef CONFIG_RTIO_SUBMIT_SEM
	Z_OOPS(Z_SYSCALL_OBJ(r->submit_sem, K_OBJ_SEM));
#endif

	return z_impl_rtio_submit(r, wait_count);
}
#include <syscalls/rtio_submit_mrsh.c>
